package cn.jingyu.deepseek.test;
import cn.jingyu.deepseek.*;import cn.jingyu.deepseek.NativeActivity;import android.app.*;import android.os.*;import android.content.*;import org.json.*;import java.lang.reflect.*;
public final class RecoverySmokeTest extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();StringBuilder report=new StringBuilder();try{NativeActivity activity=(NativeActivity)startActivitySync(new Intent(getTargetContext(),NativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Field stateField=NativeActivity.class.getDeclaredField("state");stateField.setAccessible(true);JSONObject state=(JSONObject)stateField.get(activity);JSONArray messages=state.getJSONArray("chats").getJSONObject(0).getJSONArray("messages");JSONObject last=messages.getJSONObject(messages.length()-1);if(!last.optString("status").equals("interrupted")||!last.optString("text").contains("手动续写"))throw new AssertionError("partial text not restored");report.append("PASS process restart preserves partial response and marks it interrupted\n");Field busy=NativeActivity.class.getDeclaredField("busy");busy.setAccessible(true);if((Boolean)busy.get(activity))throw new AssertionError("request restarted automatically");report.append("PASS process restart never automatically starts another paid request\n");out.putString("report",report.toString());finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("report",report+"FAIL "+e);finish(Activity.RESULT_CANCELED,out);}}
}
